/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var logger = require( 'debug' );
var isDeepEqual = require( '@stdlib/assert/deep-equal' );
var isArray = require( '@stdlib/assert/is-array' );
var isUndefined = require( '@stdlib/assert/is-undefined' );
var copyArray = require( '@stdlib/array/base/copy' );
var format = require( '@stdlib/string/format' );
var changeEvent = require( './../change_event.js' );
var prop = require( './properties.js' );


// VARIABLES //

var debug = logger( 'vega:threshold-scale:set:'+prop.name );


// MAIN //

/**
* Sets the scale domain.
*
* ## Notes
*
* -   Providing `undefined` "unsets" the configured value.
*
* @private
* @param {(Array|void)} value - input value
* @throws {TypeError} must be an array
* @returns {void}
*/
function set( value ) {
	var isArr = isArray( value );
	if ( !isArr && !isUndefined( value ) ) {
		throw new TypeError( format( 'invalid assignment. `%s` must be an array. Value: `%s`.', prop.name, value ) );
	}

	// FIXME: can we do further validation of objects (e.g., data reference or signal reference)?

	// FIXME: can we be more intelligent about deep equality comparison here in order to squeeze out some perf? E.g., by doing type specific deep equality comparisons or would that just be replicating what deep equal is doing?

	if ( isArr && isArray( this.range ) && value.length + 1 !== this.range.length ) {
		throw new TypeError( format( 'invalid assignment. `%s` length must be exactly one greater than `%s` length. %s length: `%u`. %s length: `%u`.', 'range', 'domain', 'range', this.range.length, 'domain', value.length ) );
	}
	if ( !isDeepEqual( value, this[ prop.private ] ) ) {
		value = ( isArr ) ? copyArray( value ) : value;
		debug( 'Current value: %s. New value: %s.', JSON.stringify( this[ prop.private ] ), JSON.stringify( value ) );
		this[ prop.private ] = value;
		this.emit( 'change', changeEvent( prop.name ) );
	}
}


// EXPORTS //

module.exports = set;
